	@Test
	public void shouldThrowMalformedQueryExceptionForQuerySyntaxErrors() throws Exception {
		try (TransactionCleanup cleanup = new TransactionCleanup()) {
			String testQuery = "#PREFIX ex: <http://example.com#>\n" +
					"select * where { \n" +
					"\t?s ex:data ?o .\n" +
					"}";

			Transaction txn = new Transaction(repository);
			cleanup.transaction = txn;
			ActiveTransactionRegistry.INSTANCE.register(txn);
			cleanup.registration = () -> ActiveTransactionRegistry.INSTANCE.deregister(txn);

			final UUID transactionId = txn.getID();

			request.setRequestURI("/repositories/" + repositoryID + "/transactions/" + transactionId);
			request.setPathInfo(repositoryID + "/transactions/" + transactionId);
			request.setMethod(HttpMethod.PUT.name());
			request.setParameter(Protocol.ACTION_PARAM_NAME, "QUERY");
			request.setContentType("application/sparql-query; charset=utf-8");
			request.setContent(testQuery.getBytes(StandardCharsets.UTF_8));

			TransactionController transactionController = new TransactionController();

			response = new MockHttpServletResponse();

			assertThrows(ClientHTTPException.class, () -> {
				try {
					transactionController.handleRequestInternal(request, response);
				} catch (ClientHTTPException e) {
					Assertions
							.assertEquals(
									"MALFORMED QUERY: org.eclipse.rdf4j.query.parser.sparql.ast.VisitorException: " +
											"QName 'ex:data' uses an undefined prefix",
									e.getMessage());
					throw e;
				}
			});

		}
	}

	@Test
	public void shouldReportMalformedDataForParseErrorsInAddedData() throws Exception {
		try (TransactionCleanup cleanup = new TransactionCleanup()) {
			Transaction txn = new Transaction(repository);
			cleanup.transaction = txn;
			ActiveTransactionRegistry.INSTANCE.register(txn);
			cleanup.registration = () -> ActiveTransactionRegistry.INSTANCE.deregister(txn);
			UUID transactionId = txn.getID();

			request.setRequestURI("/repositories/" + repositoryID + "/transactions/" + transactionId);
			request.setPathInfo(repositoryID + "/transactions/" + transactionId);
			request.setMethod(HttpMethod.PUT.name());
			request.setParameter(Protocol.ACTION_PARAM_NAME, "ADD");
			request.setContentType(RDFFormat.TRIG.getDefaultMIMEType());
			request.setContent("<default> <http://example.org/p> \"default\" .".getBytes(StandardCharsets.UTF_8));

			TransactionController transactionController = new TransactionController();
			ClientHTTPException exception = assertThrows(ClientHTTPException.class,
					() -> transactionController.handleRequestInternal(request, response));

			Assertions.assertEquals(400, exception.getStatusCode());
			ErrorInfo errorInfo = ErrorInfo.parse(exception.getMessage());
			Assertions.assertEquals(ErrorType.MALFORMED_DATA, errorInfo.getErrorType());
			Assertions.assertEquals("Not a valid (absolute) IRI: /default [line 1]", errorInfo.getErrorMessage());

		}
	}

	@Test
	public void shouldResolveRelativeUpdateIrisAgainstRawBaseUri() throws Exception {
		String baseURI = "https://example.org/update/";
		try (TransactionCleanup cleanup = new TransactionCleanup()) {
			Transaction txn = new Transaction(repository);
			cleanup.transaction = txn;
			ActiveTransactionRegistry.INSTANCE.register(txn);
			cleanup.registration = () -> ActiveTransactionRegistry.INSTANCE.deregister(txn);
			UUID transactionId = txn.getID();

			request.setRequestURI("/repositories/" + repositoryID + "/transactions/" + transactionId);
			request.setPathInfo(repositoryID + "/transactions/" + transactionId);
			request.setMethod(HttpMethod.PUT.name());
			request.setParameter(Protocol.ACTION_PARAM_NAME, "UPDATE");
			request.setParameter(Protocol.BASEURI_PARAM_NAME, baseURI);
			request.setContentType(Protocol.SPARQL_UPDATE_MIME_TYPE);
			request.setContent(("INSERT DATA { <relative-subject> <http://example.org/p> \"update\" }")
					.getBytes(StandardCharsets.UTF_8));

			TransactionController transactionController = new TransactionController();
			transactionController.handleRequestInternal(request, response);
		}

		try (var connection = repository.getConnection()) {
			Assertions.assertTrue(connection.hasStatement(
					SimpleValueFactory.getInstance().createIRI(baseURI + "relative-subject"),
					SimpleValueFactory.getInstance().createIRI("http://example.org/p"),
					SimpleValueFactory.getInstance().createLiteral("update"), false));
		}
	}

	@Test
	public void shouldHandleDeleteWithRepositoriesPrefixInPathInfo() throws Exception {
		try (TransactionCleanup cleanup = new TransactionCleanup()) {
			Transaction txn = new Transaction(repository);
			cleanup.transaction = txn;
			ActiveTransactionRegistry.INSTANCE.register(txn);
			cleanup.registration = () -> {
				try {
					ActiveTransactionRegistry.INSTANCE.deregister(txn);
				} catch (RepositoryException alreadyRemoved) {
					// A successful DELETE already removed this transaction from the registry.
				}
			};
			final UUID transactionId = txn.getID();

			request.setRequestURI("/repositories/" + repositoryID + "/transactions/" + transactionId);
			request.setPathInfo("/repositories/" + repositoryID + "/transactions/" + transactionId);
			request.setMethod(HttpMethod.DELETE.name());

			TransactionController transactionController = new TransactionController();
			response = new MockHttpServletResponse();

			Assertions.assertDoesNotThrow(() -> transactionController.handleRequestInternal(request, response));

		}
	}

